onClick:
{{
(async () => {
  JSutils.resetInactivityTimer();

  const isInsert = appsmith.store.modalContexto?.acaoTipo === "ADICIONAR";
  const query = isInsert ? InsertImuniza : UpdateImuniza;

  const currentID = isInsert
    ? null
    : appsmith.store.imunizaSelecionado?.imun003_id;

  const params = {
    imun003_imun001:   Number(Select1Imuniza.selectedOptionValue),
    imun003_observacao: (InputDescImuniza.text || "").trim().toUpperCase(),
    imun003_ani002_id: Number(appsmith.store.petID_Amigos),
    imun003_id:        currentID
  };

  if (isInsert && !params.imun003_imun001) {
    return showAlert("Selecione um imunizante.", "warning");
  }

  try {
    const response = await query.run(params);

    const idParaSelecionar = isInsert
      ? response[0].imun003_id
      : currentID;

    await SelectImuniza.run();

    await storeValue('idSelecionadoIMUNIZA', idParaSelecionar);
    await storeValue('imunizaSelecionado', {});

    await storeValue('modalContexto', {
      entidade: "IMUNIZA",
      acaoTipo: "EDITAR",
      acaoBotao: "ATUALIZAR"
    });

    showAlert(
      `Imunização ${isInsert ? 'incluída' : 'atualizada'} com sucesso!`,
      "success"
    );

  } catch (err) {
    showAlert("Erro ao salvar: " + err.message, "error");
  }
})()
}}
